#!/bin/sh
# Exit 0 skips; nonzero builds. See ../VERCEL_DEPLOYMENTS.md.
if [ "${VERCEL_FORCE_BUILD:-0}" = "1" ]; then exit 1; fi; base="${VERCEL_GIT_PREVIOUS_SHA:-}"; if [ -z "$base" ] || ! git cat-file -e "$base^{commit}" 2>/dev/null; then echo "Build: no usable previous deployment"; exit 1; fi; if [ "$base" = "$(git rev-parse HEAD)" ]; then echo "Build: explicit redeployment"; exit 1; fi; git diff --quiet "$base" HEAD -- ':(top,literal)sim08' ':(top,literal)package.json' ':(top,literal)package-lock.json' ':(top,literal)npm-shrinkwrap.json' ':(top,literal)pnpm-lock.yaml' ':(top,literal)pnpm-workspace.yaml' ':(top,literal)yarn.lock' ':(top,literal)bun.lock' ':(top,literal)bun.lockb' ':(top,literal).npmrc' ':(top,literal).node-version' ':(top,literal).nvmrc' ':(top,literal)vercel.json' ':(top,literal)shared' ':(top,literal)packages'
